def mincostToHireWorkers(quality: list[int], wage: list[int], k: int) -> float:
    import heapq
    workers = sorted([(w / q, q) for w, q in zip(wage, quality)])
    pq = []
    sum_q = 0
    min_cost = float('inf')
    for ratio, q in workers:
        heapq.heappush(pq, -q)
        sum_q += q
        if len(pq) > k:
            sum_q += heapq.heappop(pq)
        if len(pq) == k:
            min_cost = min(min_cost, ratio * sum_q)
    return round(min_cost, 5)

